&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types d&#39;inquisiteur&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_dinquisiteur_0&quot; href=&quot;#Les_arch&#233;types_dinquisiteur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agent-Intra&#231;able-(Inquisiteur).html&quot; title=&quot;Agent intra&#231;able&quot;&gt;Agent intra&#231;able&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brise-Sortil&#232;ge-(Inquisiteur).html&quot; title=&quot;Brise-sortil&#232;ge&quot;&gt;Brise-sortil&#232;ge&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Foi-(Inquisiteur).html&quot; title=&quot;Chasseur de foi&quot;&gt;Chasseur de foi&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Reliques-(Inquisiteur).html&quot; title=&quot;Chasseur de reliques&quot;&gt;Chasseur de reliques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Sorci&#232;res-(Inquisiteur).html&quot; title=&quot;Chasseur de sorci&#232;res&quot;&gt;Chasseur de sorci&#232;res&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Vampires-(Inquisiteur).html&quot; title=&quot;Chasseur de vampires&quot;&gt;Chasseur de vampires&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Vigilant-(Inquisiteur).html&quot; title=&quot;D&#233;fenseur vigilant&quot;&gt;D&#233;fenseur vigilant&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exarque-(Inquisiteur).html&quot; title=&quot;Exarque&quot;&gt;Exarque&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exorciste-(Inquisiteur).html&quot; title=&quot;Exorciste&quot;&gt;Exorciste&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exterminateur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Exterminateur sacr&#233;&quot;&gt;Exterminateur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extracteur-(Inquisiteur).html&quot; title=&quot;Extracteur&quot;&gt;Extracteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Tactique-(Inquisiteur).html&quot; title=&quot;Guide tactique&quot;&gt;Guide tactique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;r&#233;tique-(Inquisiteur).html&quot; title=&quot;H&#233;r&#233;tique&quot;&gt;H&#233;r&#233;tique&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Iconoclaste-(Inquisiteur).html&quot; title=&quot;Iconoclaste&quot;&gt;Iconoclaste&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Immolateur-(Inquisiteur).html&quot; title=&quot;Immolateur&quot;&gt;Immolateur&lt;/a&gt; (Ifrit) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Infiltrateur-(Inquisiteur).html&quot; title=&quot;Infiltrateur&quot;&gt;Infiltrateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Loup-Masqu&#233;-(Inquisiteur).html&quot; title=&quot;Loup masqu&#233;&quot;&gt;Loup masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mangeur-De-P&#234;ch&#233;s-(Inquisiteur).html&quot; title=&quot;Mangeur de p&#234;ch&#233;s&quot;&gt;Mangeur de p&#234;ch&#233;s&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Chasseur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Ma&#238;tre chasseur sacr&#233;&quot;&gt;Ma&#238;tre chasseur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parricide-(Inquisiteur).html&quot; title=&quot;Parricide&quot;&gt;Parricide&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html&quot; title=&quot;Les dhampirs&quot;&gt;Dhampir&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;cheur-(Inquisiteur).html&quot; title=&quot;Pr&#234;cheur&quot;&gt;Pr&#234;cheur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Des-Ombres-(Inquisiteur).html&quot; title=&quot;Traqueur des ombres&quot;&gt;Traqueur des ombres&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Nain.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Nain.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Nain.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;nains&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Le traditionalisme bougon de beaucoup de nains atteint son apog&#233;e chez ceux qui adh&#232;rent &#224; des principes orthodoxes tr&#232;s stricts ancr&#233;s dans des principes ancestraux et des pratiques anciennes inflexibles, en d&#233;pit de tous les changements et de toutes les innovations.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_0&quot; href=&quot;#Sorts_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Les exarques ne peuvent pas lancer de sorts du registre &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#CHAOS&quot; title=&quot;Cr&#233;er un sort&quot;&gt;Chaos&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Volont&#233; inflexible (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Volont&#233;_inflexible_Ext_1&quot; href=&quot;#Volont&#233;_inflexible_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Au niveau 1, l’exarque gagne un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets de confusion et d’ali&#233;nation mentale et contre les effets du registre Chaos. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#CONNAISSANCEDESMONSTRES&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;connaissance des monstres&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;tection du Chaos (Mag)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;tection_du_Chaos_Mag_2&quot; href=&quot;#D&#233;tection_du_Chaos_Mag_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
L’exarque peut utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Chaos.html&quot; title=&quot;D&#233;tection du Chaos&quot;&gt;d&#233;tection du Chaos&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#DETECTIONDALIGNEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;d&#233;tection d’alignement&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Juge terrifiant (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Juge_terrifiant_Sur_3&quot; href=&quot;#Juge_terrifiant_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Au niveau 5, l’exarque peut donner &#224; une de ses armes la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Juge.html&quot; title=&quot;juge (propri&#233;t&#233;)&quot;&gt;juge&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Mena&#231;ante.html&quot; title=&quot;mena&#231;ante (propri&#233;t&#233;)&quot;&gt;mena&#231;ante&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; et peut passer d’une propri&#233;t&#233; &#224; l’autre par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Quand il utilise l’une de ces deux propri&#233;t&#233;s, la &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes#Critique.html&quot; title=&quot;zone de critique&quot;&gt;zone de critique&lt;/a&gt; de l’arme est doubl&#233;e contre les cr&#233;atures Chaotiques. Ce pouvoir ne se cumule pas avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aff&#251;tage.html&quot; title=&quot;Aff&#251;tage&quot;&gt;aff&#251;tage&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; ou d’autres effets similaires. En dehors de cela, il fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#TUEUR&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;tueur&lt;/a&gt; et le remplace.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Aura de r&#233;p&#233;tition (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_r&#233;p&#233;tition_Sur_4&quot; href=&quot;#Aura_de_r&#233;p&#233;tition_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Au niveau 8, l’exarque peut, une fois par jour et alors qu’il utilise son &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur#Jugement.html&quot; title=&quot;jugement&quot;&gt;jugement&lt;/a&gt;, projeter une aura de r&#233;p&#233;tition, comme le pouvoir de sous-domaine du &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lartisanat.html#Sous-domaines_1&quot; title=&quot;Domaine de l&amp;#39;Artisanat&quot;&gt;Labeur&lt;/a&gt;. Si l’exarque a choisi &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lartisanat.html&quot; title=&quot;Domaine de l&amp;#39;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (Labeur) comme domaine, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de son aura augmente de 2, mais pas sa dur&#233;e d’effet. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#SECONDJUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;second jugement&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Double danger (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Double_danger_Sur_5&quot; href=&quot;#Double_danger_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Au niveau 12, quand l’exarque utilise son pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGETERRIFIANT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;juge terrifiant&lt;/a&gt;, il peut choisir d’affecter deux armes, l’une gagnant &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Mena&#231;ante.html&quot; title=&quot;mena&#231;ante (propri&#233;t&#233;)&quot;&gt;mena&#231;ante&lt;/a&gt;, l’autre &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Juge.html&quot; title=&quot;juge (propri&#233;t&#233;)&quot;&gt;juge&lt;/a&gt;. Il peut appliquer les deux &#224; une m&#234;me arme, dont la &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes#Critique.html&quot; title=&quot;zone de critique&quot;&gt;zone de critique&lt;/a&gt; possible s’en trouve doubl&#233;e. Ce pouvoir ne se cumule pas avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aff&#251;tage.html&quot; title=&quot;Aff&#251;tage&quot;&gt;aff&#251;tage&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; ou d’autres effets similaires. Il remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#TUEURSUPERIEUR&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;tueur sup&#233;rieur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Aura de r&#233;version (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Aura_de_r&#233;version_Sur_6&quot; href=&quot;#Aura_de_r&#233;version_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Au niveau 16, quand l’exarque utilise son &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur#Jugement.html&quot; title=&quot;jugement&quot;&gt;jugement&lt;/a&gt;, il peut &#233;mettre une aura de r&#233;version de 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Rayon.html&quot; title=&quot;rayon&quot;&gt;rayon&lt;/a&gt; pendant un nombre de rounds par jour &#233;gal &#224; son niveau d’&lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt;. &#192; part l’exarque, toutes les cr&#233;atures qui se trouvent dans la zone et b&#233;n&#233;ficient d’un effet de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;transmutation&lt;/a&gt; au d&#233;but de son tour deviennent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuses&lt;/a&gt; ou bien &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuses&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;euses&lt;/a&gt; si elles se trouvent sous un effet de &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;, y compris un changement de forme (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; pour annuler, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 10 + 1/2 niveau de l’exarque + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;). Les effets continus issus d’objets magiques permanents ne causent pas de tels effets. Les sorts de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation&lt;/a&gt;&lt;/i&gt; contre la transmutation gagnent un bonus de +4 quand ils agissent au sein de cette aura. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#TROISIEMEJUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;troisi&#232;me jugement&lt;/a&gt;.
